/**
 * Worker entry: the OpenNext-generated Next.js app plus an hourly
 * `scheduled` handler for the cron trigger in wrangler.jsonc.
 *
 * The scheduled handler calls the app's own refresh routes so all yarn-stock
 * logic stays in the Next.js code. A failed refresh fails the cron run, which
 * shows up under Workers → diana-flagstaff → Settings → Trigger events.
 */

/* eslint-disable @typescript-eslint/ban-ts-comment -- .open-next/ exists only after a build, so @ts-expect-error would fail either way */
// @ts-ignore `.open-next/worker.js` is generated by `opennextjs-cloudflare build`
import { default as handler } from "./.open-next/worker.js";

type Ctx = { waitUntil(promise: Promise<unknown>): void };

// Charisma isn't here: Michaels blocks Cloudflare, so its stock is pushed
// from Diana's Mac instead (scripts/push-charisma-stock.mjs).
const REFRESH_ROUTES = ["/api/cron/refresh-bobbiny"];

const worker = {
  fetch: handler.fetch,

  async scheduled(_controller: unknown, env: CloudflareEnv, ctx: Ctx) {
    const headers: Record<string, string> = env.CRON_SECRET
      ? { Authorization: `Bearer ${env.CRON_SECRET}` }
      : {};

    const results = await Promise.allSettled(
      REFRESH_ROUTES.map(async (path) => {
        const res: Response = await handler.fetch(
          new Request(`https://diana-flagstaff.cron${path}`, { method: "POST", headers }),
          env,
          ctx
        );
        const body = await res.text();
        console.log(`[cron] ${path} → ${res.status} ${body}`);
        if (!res.ok) throw new Error(`${path} → ${res.status}`);
      })
    );

    const failed = results.filter((r) => r.status === "rejected");
    if (failed.length) {
      throw new Error(`Yarn stock refresh failed: ${failed.map((r) => (r as PromiseRejectedResult).reason).join("; ")}`);
    }
  },
};

export default worker;

// @ts-ignore re-exported Durable Object classes from the generated worker
export { DOQueueHandler, DOShardedTagCache, BucketCachePurge } from "./.open-next/worker.js";
